/** VSA coaching-requirements roster: one sheet, one adult per row.
 *  Name / Age Group / Role / Team Name (+ phone, email, SafeSport flags).
 *  Head Coach and Assistant share a team. Missing kids / fields / dates
 *  stay fill-later holes — we do not invent children or extra sides.
 */

import ExcelJS from "exceljs";
import { inferYear } from "../dates";
import { norm, type League, type Team, type TeamAdult } from "../model";
import { blankLeague, cellText } from "../parse";
import { fillPlanningHoles, normalizeBracket } from "../planning";
import { fillCrowFlies, missingPieceIssues, structuralRefusals } from "../validate";
import { dedupeCoachRows, describeDedupe, type CoachRow } from "./dedupe";
import type { IntakeAttempt } from "./types";

function headerKey(cell: string): string | null {
  const n = norm(cell);
  if (!n) return null;
  if (n === "name") return "name";
  if (n === "team name" || n === "team") return "team";
  if (n === "age group" || n === "agegroup" || n === "division" || n === "bracket" || n === "age") return "age group";
  if (n === "role") return "role";
  if (n === "phone" || n === "phone number") return "phone";
  if (n === "email") return "email";
  if (n === "comments" || n === "comment") return "comments";
  if (n.includes("safesport")) return "safesport";
  if (n.includes("background")) return "background";
  if (n.includes("grassroots")) return "grassroots";
  return null;
}

function findCoachingHeader(ws: ExcelJS.Worksheet): { row: number; cols: Map<string, number> } | null {
  const maxRow = Math.min(ws.rowCount || 0, 25);
  const maxCol = Math.max(ws.columnCount || 0, 20);
  for (let r = 1; r <= maxRow; r++) {
    const cols = new Map<string, number>();
    for (let c = 1; c <= maxCol; c++) {
      const key = headerKey(cellText(ws.getRow(r).getCell(c)));
      if (key && !cols.has(key)) cols.set(key, c);
    }
    if (cols.has("name") && cols.has("team") && cols.has("age group") && (cols.has("role") || cols.has("safesport"))) {
      return { row: r, cols };
    }
  }
  return null;
}

function take(ws: ExcelJS.Worksheet, r: number, cols: Map<string, number>, key: string): string {
  const c = cols.get(key);
  if (!c) return "";
  return cellText(ws.getRow(r).getCell(c));
}

function splitName(raw: string): TeamAdult {
  const parts = raw.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return { first: "", last: "" };
  if (parts.length === 1) return { first: parts[0], last: "" };
  return { first: parts[0], last: parts.slice(1).join(" ") };
}

function isAssistant(role: string): boolean {
  return /assistant|asst\.?/i.test(role);
}

function isHead(role: string): boolean {
  if (isAssistant(role)) return false;
  return /head|coach/i.test(role);
}

function upsertAdult(team: Team, person: TeamAdult, role: string) {
  if (isAssistant(role)) {
    if (!team.assistant) team.assistant = person;
    else if (!team.coach) team.coach = person;
    return;
  }
  if (isHead(role) || !role) {
    if (!team.coach) team.coach = person;
    else if (!team.assistant) team.assistant = person;
    return;
  }
  if (!team.coach) team.coach = person;
  else if (!team.assistant) team.assistant = person;
}

function ensureAgeGroup(league: League, bracket: string) {
  if (!bracket) return;
  if (league.ageGroups.some((a) => norm(a.name) === norm(bracket))) return;
  league.ageGroups.push({
    name: bracket,
    minOnField: null,
    maxOnField: null,
    gameLengthMinutes: null,
    assistantMin: null,
    assistantPreferred: null,
    fieldClasses: [],
    mayPlayWith: [bracket],
  });
}

function sheetTitle(ws: ExcelJS.Worksheet): string {
  const t = cellText(ws.getRow(1).getCell(1));
  if (!t || headerKey(t)) return "";
  return t;
}

export function tryCoachingRequirements(wb: ExcelJS.Workbook, filename = ""): IntakeAttempt {
  const league = blankLeague();
  league.sourceName = filename || undefined;
  league.sampleOnly = false;
  const report: string[] = [];
  const untitled: string[] = [];
  const collected: CoachRow[] = [];
  let matchedSheet = false;

  for (const ws of wb.worksheets) {
    const found = findCoachingHeader(ws);
    if (!found) continue;
    matchedSheet = true;
    const title = sheetTitle(ws);
    if (title && !league.season.title) {
      league.season.title = title;
      league.season.headerTitle = title.replace(/\s+coaching roster$/i, "").trim() || title;
    }
    const maxRow = ws.rowCount || 0;
    for (let r = found.row + 1; r <= maxRow; r++) {
      collected.push({
        name: take(ws, r, found.cols, "name"),
        phone: take(ws, r, found.cols, "phone"),
        email: take(ws, r, found.cols, "email"),
        age: take(ws, r, found.cols, "age group"),
        role: take(ws, r, found.cols, "role"),
        team: take(ws, r, found.cols, "team"),
        comments: take(ws, r, found.cols, "comments"),
      });
    }
  }

  const { rows, stats } = dedupeCoachRows(collected);
  for (const row of rows) {
    if (row.name && headerKey(row.name)) continue;
    const bracket = normalizeBracket(row.age);
    const person = row.name ? { ...splitName(row.name), phone: row.phone || undefined } : undefined;
    if (person && !row.team) {
      untitled.push(printCoach(person, bracket));
      if (bracket) ensureAgeGroup(league, bracket);
      continue;
    }
    if (!row.team) continue;
    const name = row.team.trim();
    const key = `${norm(bracket)} ${norm(name)}`;
    let team = league.teams.find((t) => `${norm(t.bracket)} ${norm(t.name)}` === key);
    if (!team) {
      team = {
        name,
        bracket,
        association: "",
        jersey: "",
        players: [],
        willNotPlay: [],
        willNotTravelTo: [],
        awayDesired: 0,
        guestDesired: 0,
      };
      league.teams.push(team);
    }
    if (person) upsertAdult(team, person, row.role);
    if (row.comments && !team.jersey) {
      /* keep comment off the jersey; report only */
      report.push(`${bracket} ${name}: ${row.comments}`);
    }
    ensureAgeGroup(league, bracket);
  }

  if (!matchedSheet) {
    return { matched: false, strategy: "coaching-requirements", reason: "no Name / Age Group / Team Name roster" };
  }
  if (!league.teams.length) {
    return { matched: false, strategy: "coaching-requirements", reason: "coaching headers but no teams" };
  }

  const year = inferYear(league.season.title || filename, 2026);
  if (year && !league.season.headerTitle) league.season.headerTitle = `Fall ${year}`;
  if (/vsa|van soccer/i.test(league.season.title) || /vsa/i.test(filename)) {
    league.season.associationName = "Van Soccer Association";
  }

  fillPlanningHoles(league);
  league.travel = fillCrowFlies(league);

  const issues = [
    ...structuralRefusals(league)
      .filter((i) => i.code === "age-group-incomplete" || i.code === "leftover-sample")
      .map((i) => ({ ...i, level: "flag" as const })),
    ...missingPieceIssues(league),
  ];
  if (untitled.length) report.push(`Coaches without a team: ${untitled.join("; ")}`);
  report.push(`Coaching roster: ${league.teams.length} teams read`);
  const dedupeLine = describeDedupe(stats);
  if (dedupeLine !== "No duplicate rows.") report.push(dedupeLine);

  const hard = structuralRefusals(league).filter((i) => i.code !== "age-group-incomplete" && i.code !== "leftover-sample");
  if (hard.length) {
    return {
      matched: true,
      strategy: "coaching-requirements",
      result: { ok: false, league, issues: [...issues, ...hard], report, strategy: "coaching-requirements" },
    };
  }
  return {
    matched: true,
    strategy: "coaching-requirements",
    result: { ok: true, league, issues, report, strategy: "coaching-requirements" },
  };
}

function printCoach(p: TeamAdult, bracket: string): string {
  const who = [p.first, p.last].filter(Boolean).join(" ") || "A coach";
  return bracket ? `${who} (${bracket})` : who;
}
